package com.print.kiosk.exception;
import com.print.kiosk.dto.response.ApiErrorResponse;import jakarta.servlet.http.HttpServletRequest;import org.slf4j.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.HttpRequestMethodNotSupportedException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.*;import org.springframework.web.multipart.support.MissingServletRequestPartException;import org.springframework.web.servlet.resource.NoResourceFoundException;import java.time.*;import java.util.*;import java.util.stream.*;
@RestControllerAdvice public class GlobalExceptionHandler{private static final Logger LOGGER=LoggerFactory.getLogger(GlobalExceptionHandler.class);private static final ZoneId DHAKA=ZoneId.of("Asia/Dhaka");private static final String GENERAL="Something went wrong while processing your request. Please try again. If the problem continues, contact the Kiosk Printing Centre.";
    @ExceptionHandler(ResourceNotFoundException.class)ResponseEntity<ApiErrorResponse> notFound(ResourceNotFoundException e,HttpServletRequest r){return build(HttpStatus.NOT_FOUND,e.getMessage(),r);}
    @ExceptionHandler(DuplicateResourceException.class)ResponseEntity<ApiErrorResponse> duplicate(DuplicateResourceException e,HttpServletRequest r){return build(HttpStatus.CONFLICT,e.getMessage(),r);}
    @ExceptionHandler({InvalidCredentialsException.class,InvalidRefreshTokenException.class})ResponseEntity<ApiErrorResponse> unauthorized(RuntimeException e,HttpServletRequest r){return build(HttpStatus.UNAUTHORIZED,e.getMessage(),r);}
    @ExceptionHandler({AccountNotAllowedException.class,UnauthorizedRequestOperationException.class})ResponseEntity<ApiErrorResponse> forbidden(RuntimeException e,HttpServletRequest r){return build(HttpStatus.FORBIDDEN,e.getMessage(),r);}
    @ExceptionHandler({InvalidPinException.class,ExpiredPinException.class})ResponseEntity<ApiErrorResponse> pin(RuntimeException e,HttpServletRequest r){return build(HttpStatus.UNAUTHORIZED,e.getMessage(),r);}
    @ExceptionHandler(PinVerificationBlockedException.class)ResponseEntity<ApiErrorResponse> blocked(PinVerificationBlockedException e,HttpServletRequest r){return build(HttpStatus.TOO_MANY_REQUESTS,e.getMessage(),r);}
    @ExceptionHandler({FileValidationException.class,IllegalArgumentException.class})ResponseEntity<ApiErrorResponse> bad(RuntimeException e,HttpServletRequest r){return build(HttpStatus.BAD_REQUEST,e.getMessage(),r);}
    @ExceptionHandler(DocumentConversionException.class)ResponseEntity<ApiErrorResponse> conversion(DocumentConversionException e,HttpServletRequest r){return build(HttpStatus.UNPROCESSABLE_CONTENT,e.getMessage(),r);}
    @ExceptionHandler({PricingConflictException.class,InvalidPrintRequestStateException.class,RequestAlreadyClaimedException.class,InvalidQueueActionException.class,FileAlreadyDeletedException.class})ResponseEntity<ApiErrorResponse> conflict(RuntimeException e,HttpServletRequest r){return build(HttpStatus.CONFLICT,e.getMessage(),r);}
    @ExceptionHandler(PricingConfigurationException.class)ResponseEntity<ApiErrorResponse> unavailable(PricingConfigurationException e,HttpServletRequest r){return build(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage(),r);}
    @ExceptionHandler(MaxUploadSizeExceededException.class)ResponseEntity<ApiErrorResponse> tooLarge(MaxUploadSizeExceededException e,HttpServletRequest r){return build(HttpStatus.CONTENT_TOO_LARGE,"A file exceeds 20 MB or the complete request exceeds 100 MB",r);}
    @ExceptionHandler({MultipartException.class,MissingServletRequestPartException.class})ResponseEntity<ApiErrorResponse> multipart(Exception e,HttpServletRequest r){return build(HttpStatus.BAD_REQUEST,"The multipart request must contain one JSON part named 'request' and at least one file part named 'files'",r);}
    @ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ApiErrorResponse> integrity(DataIntegrityViolationException e,HttpServletRequest r){String id=ref();LOGGER.error("Database constraint violation. Reference ID: {}",id,e);return build(HttpStatus.CONFLICT,"The request conflicts with existing stored data. Please retry.",r,id);}
    @ExceptionHandler(NoResourceFoundException.class)ResponseEntity<ApiErrorResponse> endpoint(NoResourceFoundException e,HttpServletRequest r){return build(HttpStatus.NOT_FOUND,"Endpoint was not found",r);}
    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)ResponseEntity<ApiErrorResponse> method(HttpRequestMethodNotSupportedException e,HttpServletRequest r){return build(HttpStatus.METHOD_NOT_ALLOWED,"HTTP method is not supported for this endpoint",r);}
    @ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).distinct().collect(Collectors.joining("; "));return build(HttpStatus.BAD_REQUEST,m.isBlank()?"Request validation failed":m,r);}
    @ExceptionHandler(HttpMessageNotReadableException.class)ResponseEntity<ApiErrorResponse> unreadable(HttpMessageNotReadableException e,HttpServletRequest r){return build(HttpStatus.BAD_REQUEST,"Request body contains invalid or unsupported values",r);}
    @ExceptionHandler(Exception.class)ResponseEntity<ApiErrorResponse> unexpected(Exception e,HttpServletRequest r){String id=ref();LOGGER.error("Unexpected error. Reference ID: {}",id,e);return build(HttpStatus.INTERNAL_SERVER_ERROR,GENERAL,r,id);}
    private ResponseEntity<ApiErrorResponse> build(HttpStatus s,String m,HttpServletRequest r){return build(s,m,r,ref());}private ResponseEntity<ApiErrorResponse> build(HttpStatus s,String m,HttpServletRequest r,String id){return ResponseEntity.status(s).body(new ApiErrorResponse(LocalDateTime.now(DHAKA),s.value(),s.getReasonPhrase(),m,r.getRequestURI(),id));}private String ref(){return UUID.randomUUID().toString().substring(0,8).toUpperCase();}}